import{_ as l,o as r,c as o,a0 as n,j as e,a,t}from"./chunks/framework.jwovEGr5.js";const m=JSON.parse('{"title":"Crate: frensense-bundler - Corpus Compiler","description":"","frontmatter":{},"headers":[],"relativePath":"frensense-paper/05_CRATE_BUNDLER.md","filePath":"frensense-paper/05_CRATE_BUNDLER.md"}'),p={name:"frensense-paper/05_CRATE_BUNDLER.md"};function h(i,s,c,d,g,u){return r(),o("div",null,[s[3]||(s[3]=n(`<h1 id="crate-frensense-bundler-corpus-compiler" tabindex="-1">Crate: <code>frensense-bundler</code> - Corpus Compiler <a class="header-anchor" href="#crate-frensense-bundler-corpus-compiler" aria-label="Permalink to &quot;Crate: \`frensense-bundler\` - Corpus Compiler&quot;">​</a></h1><p><strong>Path:</strong> <code>frensense-bundler/src/</code><br><strong>Role:</strong> Offline tool. Converts a directory of <code>*_positive.*</code> / <code>*_negative.*</code> file pairs into a <code>.frc</code> binary bundle.</p><hr><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>The bundler is the &quot;training&quot; phase of Frensense. It:</p><ol><li>Reads raw corpus example files from <code>corpus/targets/</code>.</li><li>Fingerprints all of them using the engine.</li><li>Learns per-category feature weights that maximally separate positives from negatives.</li><li>Derives semantic filter constraints automatically from the positive/negative contrast.</li><li>Fits per-pattern sigmoid calibration parameters.</li><li>Serializes everything into a signed <code>.frc</code> binary that the scanner loads at startup.</li></ol><p>Running the bundler is required whenever corpus files are added or modified.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build-bundle</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --corpus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> corpus/targets/</span></span></code></pre></div><hr><h2 id="build-pipeline-builder-rs" tabindex="-1">Build Pipeline (<code>builder.rs</code>) <a class="header-anchor" href="#build-pipeline-builder-rs" aria-label="Permalink to &quot;Build Pipeline (\`builder.rs\`)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>corpus/targets/</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>1. load_corpus() - scan directory, pair positive/negative files by naming convention</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>2. analyze_file() for every corpus file → Vec&lt;FunctionFingerprint&gt;</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>3. compute_bundle_api_idf() - IDF weights for API call hashes across all corpus fingerprints</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>4. learn_category_weights() - per-category 15-d weight optimization</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>5. compute_auto_filters() - derive SemanticFilter constraints from positive/negative contrast</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>6. fit calibration - per-pattern sigmoid A, B parameters</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>7. learned_semantic_markers - discover which API calls appear in which vulnerability categories</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>8. BundlePayload { patterns, weights, filters, calibration, markers, idf_weights }</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>9. frensense_frc::write_bundle() → frensense-corpus.frc</span></span></code></pre></div><hr><h2 id="module-loader" tabindex="-1">Module: <code>loader/</code> <a class="header-anchor" href="#module-loader" aria-label="Permalink to &quot;Module: \`loader/\`&quot;">​</a></h2><h3 id="corpus-file-naming-convention" tabindex="-1">Corpus File Naming Convention <a class="header-anchor" href="#corpus-file-naming-convention" aria-label="Permalink to &quot;Corpus File Naming Convention&quot;">​</a></h3><p>Pattern files must follow this naming scheme:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{lang}_{category}_{variant}_positive.{ext}</span></span>
<span class="line"><span>{lang}_{category}_{variant}_negative.{ext}</span></span></code></pre></div><p>Examples:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts_sqli_nosql_where_positive.ts</span></span>
<span class="line"><span>ts_sqli_nosql_where_negative.ts</span></span>
<span class="line"><span>rs_path_traversal_positive.rs</span></span>
<span class="line"><span>rs_path_traversal_negative.rs</span></span></code></pre></div><p>The loader recursively scans the corpus directory, pairs files by name (strip <code>_positive</code>/<code>_negative</code>), and constructs <code>BundlePattern</code> objects.</p><h3 id="frensense-comment-block-parsing" tabindex="-1"><code>[frensense]</code> Comment Block Parsing <a class="header-anchor" href="#frensense-comment-block-parsing" aria-label="Permalink to &quot;\`[frensense]\` Comment Block Parsing&quot;">​</a></h3><p>Pattern metadata is parsed directly from the positive source file&#39;s <code>[frensense]</code> comment block using the tree-sitter AST. No sidecar TOML/YAML files.</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// [frensense]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// observation: User-controlled URL is passed to fetch() without validation.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// impact: Server can be used as proxy to reach internal services.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// improvement: Validate URL against an allowlist before fetching.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// cwe: CWE-918</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// cvss: 8.8</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// owasp: A10:2021</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// severity: critical</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// runtime_probe: ssrf</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// tier: 1</span></span></code></pre></div><p>Supported fields: <code>observation</code>, <code>impact</code>, <code>improvement</code>, <code>cwe</code>, <code>cvss</code>, <code>owasp</code>, <code>severity</code>, <code>runtime_probe</code>, <code>tier</code>, <code>exploit_scenario</code>, <code>reference</code>.</p>`,23)),e("p",null,[s[0]||(s[0]=a("Template interpolation is supported: ",-1)),e("code",null,t(i.source),1),s[1]||(s[1]=a(" and ",-1)),e("code",null,t(i.sink),1),s[2]||(s[2]=a(" are replaced at finding-emit time with the actual taint source and sink names from the match evidence.",-1))]),s[4]||(s[4]=n('<hr><h2 id="module-auto-filter-rs-discriminative-filter-learning" tabindex="-1">Module: <code>auto_filter.rs</code> - Discriminative Filter Learning <a class="header-anchor" href="#module-auto-filter-rs-discriminative-filter-learning" aria-label="Permalink to &quot;Module: `auto_filter.rs` - Discriminative Filter Learning&quot;">​</a></h2><h3 id="what-it-does" tabindex="-1">What It Does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What It Does&quot;">​</a></h3><p>For each corpus pattern pair, the auto-filter analyzer extracts structural features that distinguish the positive (vulnerable) from the negative (safe) version. These become <code>SemanticFilter</code> constraints.</p><h3 id="algorithm" tabindex="-1">Algorithm <a class="header-anchor" href="#algorithm" aria-label="Permalink to &quot;Algorithm&quot;">​</a></h3><p><strong>Positive-exclusive call targets</strong> → <code>contains_call_to</code>:</p><ul><li>Extract all function call targets from ALL positive files.</li><li>Extract all function call targets from ALL negative files.</li><li><code>contains_call_to = pos_calls - neg_calls</code> (calls that appear in positives but not negatives).</li></ul><p><strong>Negative-exclusive call targets</strong> → <code>must_not_contain_call_to</code>:</p><ul><li><code>must_not_contain_call_to = neg_calls - pos_calls</code> (calls exclusive to negatives).</li></ul><p><strong>Node type exclusions</strong> → <code>must_not_contain_node_type</code>:</p><ul><li>Extract AST keyword tokens (try/catch blocks, sanitizer patterns) from negatives.</li><li>If a token appears in ALL negatives but no positives, add it as an exclusion.</li></ul><p><strong>Function name patterns</strong> → <code>must_not_match_function_name</code>:</p><ul><li>If ALL negative files contain functions matching a naming pattern absent from positives, exclude it.</li></ul><h3 id="what-was-intentionally-removed" tabindex="-1">What Was Intentionally Removed <a class="header-anchor" href="#what-was-intentionally-removed" aria-label="Permalink to &quot;What Was Intentionally Removed&quot;">​</a></h3><p>The category-level cross-pattern exclusivity loop was removed. Grouping patterns by category prefix (e.g., <code>&quot;ns&quot;</code>) and learning shared constraints caused every pattern in a category to require the same imports even when only a subset used them. Per-pattern negative-exclusivity is the correct mechanism.</p><h3 id="cs-theory" tabindex="-1">CS Theory <a class="header-anchor" href="#cs-theory" aria-label="Permalink to &quot;CS Theory&quot;">​</a></h3><p>This is <strong>discriminative feature selection</strong> - finding features that distinguish class A (positive/vulnerable) from class B (negative/safe). Analogous to:</p><ul><li>Naive Bayes feature selection: keep features with high mutual information with the class label.</li><li>SVM support vectors: the constraints act as the margin boundary.</li></ul><p>The key difference from supervised ML: the &quot;features&quot; here are boolean (call present/absent), and the &quot;classifier&quot; is a conjunction of constraints - no probability distribution needed.</p><hr><h2 id="module-pattern-weight-learner-rs-per-category-weight-learning" tabindex="-1">Module: <code>pattern/weight_learner.rs</code> - Per-Category Weight Learning <a class="header-anchor" href="#module-pattern-weight-learner-rs-per-category-weight-learning" aria-label="Permalink to &quot;Module: `pattern/weight_learner.rs` - Per-Category Weight Learning&quot;">​</a></h2><h3 id="what-it-does-1" tabindex="-1">What It Does <a class="header-anchor" href="#what-it-does-1" aria-label="Permalink to &quot;What It Does&quot;">​</a></h3><p>For each vulnerability category (e.g., <code>&quot;sqli&quot;</code>, <code>&quot;ssrf&quot;</code>, <code>&quot;cmdi&quot;</code>), learn a 15-element weight vector <code>w ∈ ℝ^15</code> such that:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>score(positive, w) &gt; score(negative, w)</span></span></code></pre></div><p>for the maximum number of corpus pairs.</p><h3 id="algorithm-1" tabindex="-1">Algorithm <a class="header-anchor" href="#algorithm-1" aria-label="Permalink to &quot;Algorithm&quot;">​</a></h3><p>Uses a simple gradient-free approach:</p><ol><li>For each category, collect all (positive_fp, negative_fp) pairs.</li><li>Score each pair using the default weights.</li><li>For pairs where positive score ≤ negative score (incorrectly ranked), adjust weights to increase the incorrectly-scored dimensions.</li><li>Iterate to convergence or a fixed number of epochs.</li></ol><p>The learned weights are stored in <code>category_weights: HashMap&lt;String, [f64; 15]&gt;</code> inside <code>PatternRegistry</code>.</p><h3 id="why-not-gradient-descent" tabindex="-1">Why Not Gradient Descent? <a class="header-anchor" href="#why-not-gradient-descent" aria-label="Permalink to &quot;Why Not Gradient Descent?&quot;">​</a></h3><p>Gradient descent requires differentiating through the Jaccard similarity function, which involves set intersection/union operations on integer hash vectors. These are not differentiable. The current approach is a perceptron-style update rule that works well on the relatively small corpus sizes (typically 100-500 patterns).</p><hr><h2 id="module-calibration-rs-sigmoid-calibration" tabindex="-1">Module: <code>calibration.rs</code> - Sigmoid Calibration <a class="header-anchor" href="#module-calibration-rs-sigmoid-calibration" aria-label="Permalink to &quot;Module: `calibration.rs` - Sigmoid Calibration&quot;">​</a></h2><h3 id="purpose-1" tabindex="-1">Purpose <a class="header-anchor" href="#purpose-1" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>Raw similarity scores are not calibrated probabilities. A score of 0.7 does not mean 70% confidence. Sigmoid calibration fits a function:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P(match | score) = σ(A · score + B) = 1 / (1 + e^{-(A·score + B)})</span></span></code></pre></div><h3 id="fitting" tabindex="-1">Fitting <a class="header-anchor" href="#fitting" aria-label="Permalink to &quot;Fitting&quot;">​</a></h3><p>For each pattern, run the scorer on all corpus positive and negative fingerprints, collect <code>(score, label)</code> pairs where <code>label = 1</code> for positives and <code>label = 0</code> for negatives. Fit <code>(A, B)</code> using maximum likelihood estimation (logistic regression without regularization, since the corpus is small).</p><p>The fitted parameters are stored in <code>pattern_calibration: HashMap&lt;String, (f32, f32)&gt;</code>.</p><p><strong>CS Theory:</strong> Platt scaling, probability calibration, logistic regression, maximum likelihood estimation.</p><hr><h2 id="bundle-payload-bundlepayload" tabindex="-1">Bundle Payload (<code>BundlePayload</code>) <a class="header-anchor" href="#bundle-payload-bundlepayload" aria-label="Permalink to &quot;Bundle Payload (`BundlePayload`)&quot;">​</a></h2><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BundlePayload</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    pub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> patterns</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">                 Vec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BundlePattern</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    pub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> category_weights</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">         Vec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">f64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; 15])&gt;,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    pub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> auto_filter_stats</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        Option</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AutoFilterStats</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    pub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pattern_calibration</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">      HashMap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">f32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">f32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)&gt;,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    pub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> learned_semantic_markers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HashMap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    pub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> api_idf_weights</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">          HashMap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">u64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">f32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>All fields are serialized together and signed with BLAKE3. The engine deserializes this once at startup and populates <code>PatternRegistry</code>.</p>',44))])}const y=l(p,[["render",h]]);export{m as __pageData,y as default};
